import{_ as n,C as s,c as a,o as c,ai as i,j as o,a as d,G as l}from"./chunks/framework.C2UmAmZ4.js";const b=JSON.parse('{"title":"What is a GeoRegion?","description":"","frontmatter":{},"headers":[],"relativePath":"georegions.md","filePath":"georegions.md","lastUpdated":null}'),r={name:"georegions.md"},p={class:"jldocstring custom-block",open:""};function g(h,e,u,y,G,m){const t=s("Badge");return c(),a("div",null,[e[3]||(e[3]=i('<h1 id="What-is-a-GeoRegion?" tabindex="-1">What is a GeoRegion? <a class="header-anchor" href="#What-is-a-GeoRegion?" aria-label="Permalink to &quot;What is a GeoRegion? {#What-is-a-GeoRegion?}&quot;">​</a></h1><p>In essence, a <code>GeoRegion</code> is:</p><ul><li><p>a geographical region of interest</p></li><li><p>identified by an <code>ID</code></p></li><li><p>a subregion of a <strong>parent</strong> <code>GeoRegion</code> (identified by <code>pID</code>, which must also be a valid <code>ID</code>)</p></li></ul><div class="tip custom-block"><p class="custom-block-title">Default GeoRegions</p><p>When using GeoRegions.jl, the default <code>GeoRegion</code> should generally be the global domain, specified by <code>GLB</code> and given by the <code>[N,S,E,W]</code> coordinates <code>[90,-90,360,0]</code>. The Global GeoRegion <code>GLB</code> is considered to be a subset of itself.</p></div>',4)),o("details",p,[o("summary",null,[e[0]||(e[0]=o("a",{id:"GeoRegions.AbstractGeoRegion",href:"#GeoRegions.AbstractGeoRegion"},[o("span",{class:"jlbinding"},"GeoRegions.AbstractGeoRegion")],-1)),e[1]||(e[1]=d()),l(t,{type:"info",class:"jlObjectType jlType",text:"Type"})]),e[2]||(e[2]=i('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AbstractGeoRegion</span></span></code></pre></div><p>Abstract supertype for geographical regions. All <code>AbstractGeoRegion</code> types contain the following fields:</p><ul><li><p><code>ID</code> - A <code>String</code> Type, the identifier for the GeoRegion.</p></li><li><p><code>pID</code> - A <code>String</code> Type, the identifier for the parent GeoRegion.</p></li><li><p><code>name</code> - A <code>String</code> Type, the full name of the GeoRegion.</p></li><li><p><code>path</code> - A <code>String</code> Type, the path of the file containing information on this GeoRegion.</p></li><li><p><code>N</code> - A <code>Float</code> Type, contains the northernmost latitude bound.</p></li><li><p><code>S</code> - A <code>Float</code> Type, contains the southernmost latitude bound.</p></li><li><p><code>E</code> - A <code>Float</code> Type, contains the easternmost longitude bound.</p></li><li><p><code>W</code> - A <code>Float</code> Type, contains the westernmost longitude bound.</p></li><li><p><code>θ</code> - A <code>Float</code> Type, the rotation projection for the data in the GeoRegion</p></li><li><p><code>geometry</code> - A <code>Geometry</code> or <code>Vector{Geometry}</code> Type</p></li></ul><p><a href="https://github.com/GeoRegionsEcosystem/GeoRegions.jl/blob/6aaab4bfe8e7242104ccbd5c9af1e4cee435d44e/src/GeoRegions.jl#L27-L41" target="_blank" rel="noreferrer">source</a></p>',4))]),e[4]||(e[4]=i('<h2 id="The-GeoRegion-Type" tabindex="-1">The <code>GeoRegion</code> Type <a class="header-anchor" href="#The-GeoRegion-Type" aria-label="Permalink to &quot;The `GeoRegion` Type {#The-GeoRegion-Type}&quot;">​</a></h2><p>In GeoRegions.jl v8 and above, we have standardized the usage of the struct type <code>GeoRegion</code> for all simple polygonal shapes.</p><p><strong>Current Limitations:</strong></p><ul><li><p>A <code>GeoRegion</code> supports only one shape/polygon per GeoRegion</p></li><li><p>A <code>GeoRegion</code> shape/polygon cannot have holes within it</p></li></ul><p>Work is currently in progress to determine how best to include multiple shapes in a single <code>GeoRegion</code> type.</p><div class="warning custom-block"><p class="custom-block-title"><code>Types</code> of GeoRegions for versions ≤v7</p><p>Previous versions of GeoRegions.jl used to differentiate between Rectilinear (<code>RectRegion</code>) and Polygonal (<code>PolyRegion</code>) Types of GeoRegions. This is no longer supported in ≥v8.</p></div><div class="warning custom-block"><p class="custom-block-title">Missing docstring.</p><p>Missing docstring for <code>GeoRegion.GeoRegion</code>. Check Documenter&#39;s build log for details.</p></div><h2 id="The-Geometry-Type" tabindex="-1">The <code>Geometry</code> Type <a class="header-anchor" href="#The-Geometry-Type" aria-label="Permalink to &quot;The `Geometry` Type {#The-Geometry-Type}&quot;">​</a></h2><p>All <code>GeoRegion</code>s are defined based on a <code>Geometry</code> struct type that contains information on the geometry of a GeoRegion.</p><div class="warning custom-block"><p class="custom-block-title">Missing docstring.</p><p>Missing docstring for <code>GeoRegion.Geometry</code>. Check Documenter&#39;s build log for details.</p></div><p>GeoRegions.jl extracts the <code>Polygon</code> and <code>Vector{Point}</code> information from this <code>Geometry</code> type and use the functionalities of <a href="https://github.com/JuliaGeo/GeometryOps.jl" target="_blank" rel="noreferrer">GeometryOps.jl</a> to perform checks on polygons.</p>',11))])}const T=n(r,[["render",g]]);export{b as __pageData,T as default};
